public String format(LoggingEvent event) {
    String message = event.getMessage();
    // Pattern for parsing the conversion specifiers
    Pattern pattern = Pattern.compile("\\{(\\w+)(?:\\:([^\\}]*))?\\}");
    Matcher matcher = pattern.matcher(message);
    StringBuffer formattedMessage = new StringBuffer();
    while (matcher.find()) {
        String conversionSpecifier = matcher.group(1);
        String conversionArg = matcher.group(2);
        // Convert the conversion specifier to a method name
        String methodName = "format" + conversionSpecifier.substring(0, 1).toUpperCase() + conversionSpecifier.substring(1);
        try {
            Method method = this.getClass().getMethod(methodName, event.getClass());
            Object result = method.invoke(this, event);
            formattedMessage.append(result);
        } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
            formattedMessage.append("CONVERSION FAILED");
        }
    }
    return formattedMessage.toString();
}

