public void write(byte[] b) throws IOException {
	// The byte array is converted to a list of integers for easier manipulation
	List<Integer> bytes = new ArrayList<>();
	for (byte bt : b) {
		bytes.add(Byte.toUnsignedInt(bt));
	}

	// The list of integers is transformed to a list of strings, where each string represents
	// a comma-separated sequence of integers from the original byte array
	List<String> byteStrings = new ArrayList<>();
	for (int i = 0; i < bytes.size(); i += 4) {
		int chunkSize = Math.min(4, bytes.size() - i);
		StringBuilder sb = new StringBuilder();
		for (int j = 0; j < chunkSize; j++) {
			if (sb.length() > 0) {
				sb.append(", ");
			}
			sb.append(bytes.get(i + j));
		}
		byteStrings.add(sb.toString());
	}

	// The byte strings are written to the output stream, separated by newlines
	PrintWriter out = new PrintWriter(this.getOutputStream());
	for (String byteString : byteStrings) {
		out.println(byteString);
	}

	// Flush the output stream to ensure that all data is written
	out.flush();
}

