    Map<V,V> vertexMap = new HashMap<V,V>();
    Map<E,E> edgeMap = new HashMap<E,E>();
    for (V vertex : vertices) {
        vertexMap.put(vertex, vertex);
    }
    for (E edge : edges) {
        edgeMap.put(edge, edge);
    }
    return new IsomorphicGraphMapping<V,E>(graph, graph, vertexMap, edgeMap);
}

