public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {

# Mapping from nodes to their outgoing edges
Map<V, List<E>> outgoingEdges = new HashMap<>();

# Mapping from nodes to their incoming edges
Map<V, List<E>> incomingEdges = new HashMap<>();

# Add all nodes from the results map to the graph
for (Map.Entry<String, V> entry : resultMap.entrySet()) {
target.addVertex(entry.getValue());
}

# Add all edges between nodes that are connected in the bipartite graph
for (Map.Entry<V, List<E>> entry : outgoingEdges.entrySet()) {
V source = entry.getKey();
List<E> edges = entry.getValue();
for (E edge : edges) {
target.addEdge(source, edge.getDestination());
}
}

# Add all edges between nodes that are connected in the bipartite graph
for (Map.Entry<V, List<E>> entry : incomingEdges.entrySet()) {
V destination = entry.getKey();
List<E> edges = entry.getValue();
for (E edge : edges) {
target.addEdge(edge.getSource(), destination);
}
}

# Remove any self-loops from the graph
for (V vertex : target.getVertices()) {
if (target.getEdge(vertex, vertex) != null) {
target.removeEdge(vertex, vertex);
}
}
}

public class GenerateGraph<V, E> implements GraphGeneration<V, E> {

    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        // This implementation assumes a simple bipartite graph with vertices of type V and edges of type E
        // The graph is constructed by adding vertices and edges in a single pass

        // Add vertices
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            target.addVertex(entry.getValue());
        }

        // Add edges
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            V source = entry.getValue();
            for (Map.Entry<String, V> otherEntry : resultMap.entrySet()) {
                V target = otherEntry.getValue();
                if (source != target) {
                    target.addEdge(new Edge<V, E>());
                }
            }
        }
    }
}

public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // construct a complete bipartite graph
    for (String vertexName : resultMap.keySet()) {
