        target.addVertex(vertex);
    }
    for (String vertexName1 : resultMap.keySet()) {
        for (String vertexName2 : resultMap.keySet()) {
            if (!vertexName1.equals(vertexName2)) {
                V vertex1 = resultMap.get(vertexName1);
                V vertex2 = resultMap.get(vertexName2);
                target.addEdge(vertex1, vertex2);
            }
        }
    }
}

