    diffMappings.remove("_source");

    // 2. Get history mapping from Elasticsearch.
    Mappings historyMappings = this.indicesService.getMapping(tableName);

    // 3. Compare incoming mappings with history mappings.
    Map<String, Object> diffFields = Maps.newHashMap();
    for (String field : diffMappings.keys()) {
        Object incomingValue = diffMappings.get(field);
        Object historyValue = historyMappings.get(field);

        if (incomingValue == null) {
            // Field exists in history mapping, but not in incoming mappings.
            // Index structure needs to be updated.
            diffFields.put(field, historyValue);
        } else if (historyValue == null) {
            // Field does not exist in history mapping, but exists in incoming mappings.
            // Index structure needs to be updated.
            diffFields.put(field, incomingValue);
        } else {
            if (!Objects.equals(incomingValue, historyValue)) {
                // Field exists in both mappings, but values are different.
                // Index structure needs to be updated.
                diffFields.put(field, incomingValue);
            }
        }
    }

    // 4. Create a new mappings instance with the differences.
    Mappings diffMappings = new Mappings(diffFields);
    return diffMappings;
}

