static long compressTimeBucket(long timeBucket, int dayStep) {
    long result = 0;
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);
    int newDay = (int) Math.floor(day / dayStep) * dayStep;
    result = (year * 10000) + (month * 100) + newDay;
    return result;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
  long result = timeBucket;

  if (dayStep > 0) {
    long daysSinceEpoch = result % 1000000L;
    long stepCount = daysSinceEpoch / dayStep;
    long stepOffset = daysSinceEpoch % dayStep;

    if (stepOffset >= dayStep / 2) {
      stepCount += 1;
    }

    result = result - stepOffset + stepCount * dayStep;
  }

  return result;
}

long compressTimeBucket(long timeBucket, int dayStep) {
    // Get the date from the time bucket
    LocalDate date = LocalDate.ofEpochDay(timeBucket / 1000000);

    // Get the year and month from the date
    int year = date.getYear();
    int month = date.getMonthValue();

    // Calculate the first day of the month and year
    LocalDate firstDayOfMonth = LocalDate.of(year, month, 1);

    // Calculate the number of days between the first day of the month and the date
    int daysSinceFirstDayOfMonth = (int) ChronoUnit.DAYS.between(firstDayOfMonth, date);

    // Calculate the new time bucket by adding the days since the first day of the month to the first day of the month
    long newTimeBucket = firstDayOfMonth.toEpochDay() * 1000000 + daysSinceFirstDayOfMonth * 1000000 / dayStep;

    return newTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
if (timeBucket <= 0 || dayStep <= 0) {
throw new IllegalArgumentException("timeBucket and dayStep must be positive integers");
}

long days = timeBucket % 100;
long years = timeBucket / 100;

long stepBack = (days - 1) / dayStep * dayStep;
long newDays = stepBack + dayStep;

if (newDays > days) {
newDays = days;
}

return (years * 100) + newDays;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the re-formatted time bucket
    long reFormattedTimeBucket = timeBucket - (timeBucket % dayStep);

    // If the re-formatted time bucket is less than the original time bucket, it means that the time bucket is not a multiple of the day step, so we need to add one day step to the re-formatted time bucket
    if (reFormattedTimeBucket < timeBucket) {
        reFormattedTimeBucket += dayStep;
    }
    return reFormattedTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
	int size = 0;
	for (int i = 0; i < len; i++) {
		char c = str.charAt(index + i);
		if (c <= 0x7F) {
			size++;
		} else if (c > 0x7FF) {
			size += 3;
		} else {
			size += 2;
		}
	}
	return size;
}

public class TextUtil {
    public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        int size = 0;
        for (int i = index; i < len; i++) {
            char ch = str.charAt(i);
            if (ch <= 0x7F) {
                size += 1;
            } else if (ch <= 0x7FF) {
                size += 2;
            } else if (Character.isHighSurrogate(ch)) {
                size += 4;
                i++;
            } else {
                size += 3;
            }
        }
        return size;
    }
}

