public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {

    // Enlarge the byte vector if necessary.
    int currentLength = this.length();
    int newLength = currentLength + byteLength;
    if (newLength > this.data.length) {
        this.enlargeBuffer(newLength);
    }

    // Copy the bytes into the byte vector.
    System.arraycopy(byteArrayValue, byteOffset, this.data, currentLength, byteLength);

    // Update the length of the byte vector.
    this.length += byteLength;

    return this;
}

