public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if(byteArrayValue == null) {
        byte[] nullByteArray = new byte[byteLength];
        return putByteArray(nullByteArray, 0, byteLength);
    } else {
        int length = byteArrayValue.length - byteOffset;
        if(byteLength > length) {
            throw new IllegalArgumentException("byteLength > byteArrayValue.length - offset");
        }
        int remainingBytes = byteLength % 8;
        do {
            if(remainingBytes < 0) {
                byteArrayValue[byteOffset + byteLength - 1] = 0;
            }
            remainingBytes -= 8;
        } while(remainingBytes >= 0);

        return putByteArray(byteArrayValue, byteOffset, byteLength);
    }
}

