public static void writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
	byte[] strBytes = str.getBytes(StandardCharsets.UTF_8);
	int offset = 0;
	while (offset < strBytes.length) {
		int bytesWritten = Math.min(strBytes.length - offset, lb.size - lb.offset);
		System.arraycopy(strBytes, offset, lb.buffer, lb.offset, bytesWritten);
		lb.offset += bytesWritten;
		offset += bytesWritten;
	}
}

