	int utf8Length = Utf8.encodedLength(str);

	if (utf8Length > Constant.MAX_UTF8_SIZE) {
		throw new IndexOutOfBoundsException("String exceeds maximum UTF8 size of " + Constant.MAX_UTF8_SIZE + " bytes.");
	}

	int bufferSize = session.buffer().readableBytes();
	ByteBuf buffer = session.buffer();

	if (bufferSize < (utf8Length + 1)) {
		bufferSize = utf8Length + 1;
	}

	int index = 0;
	int writeIndex = buffer.writerIndex();
	int endIndex = buffer.writerIndex() + utf8Length;

	while (index < endIndex) {
		buffer.writeByte(str.charAt(index++));
	}

	buffer.writeByte(0);
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
	final int length = str.length();
	final int index = lb.index;
	final byte[] data = lb.data;
  for (int i = 0; i < length; i++) {
		final int c = str.charAt(i);
    if (c <= 0x7F) {
			data[index + i] = (byte) c;
		} else if (c <= 0x7FF) {
			data[index + i] = (byte) (0xC0 | c >> 6);
			data[index + i + 1] = (byte) (0x80 | c & 0x3F);
			i++;
		} else {
			data[index + i] = (byte) (0xE0 | c >> 12);
			data[index + i + 1] = (byte) (0x80 | c >> 6 & 0x3F);
			data[index + i + 2] = (byte) (0x80 | c & 0x3F);
			i += 2;
		}
	}
	return new LinkedBuffer(data, index + length);
}

