public static StringBuilder substVars(StringBuilder buf, Properties props) {
    int startIndex = 0;
    int endIndex = 0;
    while (startIndex < buf.length()) {
        while (startIndex < buf.length() && buf.charAt(startIndex) != '$') {
            // Consume non-dollar text and remember the start index
            startIndex++;
        }
        if (startIndex < buf.length() && buf.charAt(startIndex) == '$') {
            // Scan the index up until the next non-dollar character
            endIndex = startIndex;
            while (endIndex < buf.length() && buf.charAt(endIndex) != '$') {
                endIndex++;
            }
            if (endIndex > startIndex) {
                String varName = buf.substring(startIndex + 1, endIndex);
                String varValue = props.getProperty(varName);
                if (varValue == null) {
                    // No value was provided for the variable in the properties
                    throw new IllegalArgumentException("No value provided for variable '" + varName + "'");
                } else {
                    // Replace the variable with its value
                    buf.replace(startIndex, endIndex + 1, varValue);
                }
            }
        }
        startIndex = endIndex;
    }
    return buf;
}

