  int bytesRead = in.read(bytes, readPointer, Math.min(bytes.length - readPointer, in.available()));

  readPointer += bytesRead;

  while (bytesRead > 0) {
    bytesRead = in.read(bytes, readPointer, Math.min(bytes.length - readPointer, in.available()));
    readPointer += bytesRead;
  }

  // Reset read pointer to start of buffer
  in.reset();
}

