    // write the serializable fields of this object to the JSONWriter
    writer.writeObjectStart();
    writer.writeObjectFieldStart("type");
    writer.writeString("SERIALIZABLE");
    writer.writeObjectFieldStart("features");
    writer.writeStringArray(features);
    writer.writeObjectEnd();

    return writer.toString();
}

public String toString(JSONWriter.Feature... features) {
    boolean pretty = false;
    if (features != null && features.length > 0) {
        for (JSONWriter.Feature f : features) {
            if (f == JSONWriter.Feature.PRETTY) {
                pretty = true;
                break;
            }
        }
    }
    JSONObject json = new JSONObject();
    json.put("features", features);
    JSONWriter writer = new JSONWriter(json, pretty);
    return writer.write();
}

