protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type for conversion cannot be null");
    }
    if (value == null) {
        return null;
    }
    if (!(value instanceof Character)) {
        throw new IllegalArgumentException("Value to be converted must be a Character");
    }
    Character charValue = (Character) value;
    if (type.isAssignableFrom(Character.class)) {
        return charValue;
    }
    if (type.isAssignableFrom(String.class)) {
        return charValue.toString();
    }
    if (type.isAssignableFrom(Integer.class) || type.isAssignableFrom(int.class)) {
        return (int) charValue.charValue();
    }
    if (type.isAssignableFrom(Long.class) || type.isAssignableFrom(long.class)) {
        return (long) charValue.charValue();
    }
    if (type.isAssignableFrom(Float.class) || type.isAssignableFrom(float.class)) {
        return (float) charValue.charValue();
    }
    if (type.isAssignableFrom(Double.class) || type.isAssignableFrom(double.class)) {
        return (double) charValue.charValue();
    }
    if (type.isAssignableFrom(Byte.class) || type.isAssignableFrom(byte.class)) {
        return (byte) charValue.charValue();
    }
    if (type.isAssignableFrom(Short.class) || type.isAssignableFrom(short.class)) {
        return (short) charValue.charValue();
    }

@Override
protected Object convertToType(Class<?> type, Object value) throws Exception {
Character convertedValue = null;
if (value instanceof Character) {
convertedValue = (Character) value;
} else if (value instanceof Number) {
int intValue = ((Number) value).intValue();
if (intValue >= 0 && intValue <= 127) {
convertedValue = (char) intValue;
}
} else if (value instanceof String) {
String stringValue = (String) value;
if (stringValue.length() == 1) {
convertedValue = stringValue.charAt(0);
}
}
if (convertedValue == null) {
throw new Exception("Cannot convert " + value + " to java.lang.Character");
}
return convertedValue;
}

