        return 2;
    }
    if (desiredCapacity % 2 == 0) {
        desiredCapacity++;
    }
    int closestPrime = 3;
    while (closestPrime < desiredCapacity) {
        if (isPrime(closestPrime)) {
            return closestPrime;
        }
        closestPrime += 2;
    }
    return closestPrime;
}

