        StringBuilder unescaped = new StringBuilder();
        for(int i = 0; i < str.length(); i++)
        {
            char c = str.charAt(i);
            if(c == '\\') 
            {
                i++;
                if(i < str.length()) 
                {
                    char next = str.charAt(i);
                    switch(next)
                    {
                        case '\\':
                            unescaped.append('\\');
                            break;
                        case 'n':
                            unescaped.append('\n');
                            break;
                        default:
                            unescaped.append(c).append(next);
                    }
                }
                else
                {
                    unescaped.append(c);
                }
            }
            else
            {
                unescaped.append(c);
            }
        }
