    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop);

    // Iterate through the nodes in the component using the given direction
    while (circulator.hasNext()) {
        Node node = circulator.next();

        // Check if the current node satisfies the predicate
        if (predicate.test(node)) {
            // Return the circulator to the node
            return circulator;
        }
    }

    // If no node satisfies the predicate, return the circulator to the stop node
    return circulator;
}

