    // Check if a similar item already exists in the constant pool
    ConstantNameAndTypeInfo constantNameAndTypeInfo = constantPool.findConstantNameAndType(name, descriptor);
    if (constantNameAndTypeInfo != null) {
        return constantNameAndTypeInfo.index;
    }

    // If not, create a new constant and add it to the constant pool
    constantNameAndTypeInfo = new ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(constantNameAndTypeInfo);
    return constantNameAndTypeInfo.index;
}

