        Constant constant = constants.get(i);
        if (constant instanceof ConstantNameAndType) {
            ConstantNameAndType nameAndType = (ConstantNameAndType) constant;
            if (nameAndType.getName(constantPool).equals(name) && nameAndType.getDescriptor(constantPool).equals(descriptor)) {
                constantIndex = i;
                break;
            }
        }
    }
    if (constantIndex == -1) {
        constants.add(new ConstantNameAndType(name, descriptor));
        constantIndex = constants.size() - 1;
    }
    return constantIndex;
}

int addConstantNameAndType(final String name, final String descriptor) {
    int hashCode = name.hashCode() ^ descriptor.hashCode();
    int index = hashCode % symbols.length;
    Symbol symbol = symbols[index];
    while (symbol != null) {
        if (symbol.type == SymbolType.CONSTANT_NAME_AND_TYPE && symbol.name.equals(name) && symbol.descriptor.equals(descriptor)) {
            return symbol.getValue();
        }
        symbol = symbol.next;
    }
    symbol = new Symbol(SymbolType.CONSTANT_NAME_AND_TYPE, name, descriptor, ++constantPoolCount);
    symbol.next = symbols[index];
    symbols[index] = symbol;
    return symbol.getValue();
}

