public class ClassFinder {
    private final List<ClassLoader> loaders = new ArrayList<>();

    public ClassFinder() {
        loaders.add(Thread.currentThread().getContextClassLoader());
    }

    public void addLoader(ClassLoader loader) {
        loaders.add(loader);
    }

    public void removeLoader(ClassLoader loader) {
        loaders.remove(loader);
    }

    public void clear() {
        loaders.clear();
    }

    public Class findClass(String className) throws ClassNotFoundException {
        for (ClassLoader loader : loaders) {
            try {
                return loader.loadClass(className);
            } catch (ClassNotFoundException e) {
                // Ignore and continue
            }
        }
        throw new ClassNotFoundException(className);
    }
}

private Class findClass(final String className) throws ClassNotFoundException {
  // Get the class loader for the current thread
  ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

  // Try to load the class using the class loader
  Class<?> clazz = classLoader.loadClass(className);

  // If the class was not found, throw an exception
  if (clazz == null) {
    throw new ClassNotFoundException("Class " + className + " not found");
  }

  return clazz;
}

