public List<SequenceRange> buildSequenceRanges(){

    // initialize variables
    int currentProfileCount = 0;
    int currentSegmentLength = 0;

    // create a list to store the sequence ranges
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // loop through the profiles
    for (Profile profile : profiles) {
        if (currentSegmentLength + profile.length <= maxSegmentLength) {
            // update the length of the current segment
            currentSegmentLength += profile.length;

            // update the number of profiles in the current segment
            currentProfileCount++;
        } else {
            // create a new sequence range and add it to the list
            sequenceRanges.add(new SequenceRange(currentProfileCount, currentSegmentLength));

            // reset the length and number of profiles for the new segment
            currentSegmentLength = profile.length;
            currentProfileCount = 1;
        }
    }

    // add the last sequence range to the list
    sequenceRanges.add(new SequenceRange(currentProfileCount, currentSegmentLength));

    return sequenceRanges;
}

