public static String stripFilenameExtension(String path){
    if(path == null) {
        return null;
    }
    int filenameIndex = path.lastIndexOf("/");
    if(filenameIndex == -1) {
        return path;
    }
    String filename = path.substring(filenameIndex + 1);
    String ext = FilenameUtils.getExtension(filename);
    if(ext.isEmpty()) {
        return path;
    }
    return path.substring(0, filenameIndex) + "/" + filename.substring(0, filename.length() - ext.length() - 1);
}

public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int extPos = path.lastIndexOf(".");
    if (extPos == -1) {
        return path;
    }
    return path.substring(0, extPos);
}

public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int filenameStart = path.lastIndexOf("/");
    if (filenameStart == -1) {
        filenameStart = 0;
    } else {
        filenameStart++;
    }
    int extensionStart = path.lastIndexOf(".");
    if (extensionStart == -1 || extensionStart < filenameStart) {
        return path;
    } else {
        return path.substring(0, extensionStart);
    }
}

