private List<Pair<Integer, Integer>> computeMinimalSeparator(int source, E e) {
List<Pair<Integer, Integer>> separator = new ArrayList<>();

for (int i = 0; i < graph.getVertexSet().size(); i++) {
if (i == source || i == e.getTarget() || i == e.getSource()) {
continue;
}

int count = 0;
for (E e2 : graph.getEdges(i, e.getTarget())) {
count++;
}

if (count == 0) {
separator.add(new Pair<>(i, e.getTarget()));
}

count = 0;
for (E e2 : graph.getEdges(i, e.getSource())) {
count++;
}

if (count == 0) {
separator.add(new Pair<>(i, e.getSource()));
}
}

return separator;
}

