    int depth = opStack.size();
    int popped = 0;
    // pop the arguments off the operand stack
    while (popped < depth) {
        if (descriptor.charAt(popped) == 'L' || descriptor.charAt(popped) == '[') {
            // if the argument is a reference, pop it from the operand stack
            opStack.pop();
        } else if (descriptor.charAt(popped) == 'D' || descriptor.charAt(popped) == 'F') {
            // if the argument is a double or float, pop it from the operand stack
            opStack.pop();
        } else if (descriptor.charAt(popped) == 'J') {
            // if the argument is a long, pop it from the operand stack
            opStack.pop();
        } else {
            // if the argument is a primitive type, pop it from the operand stack
            opStack.pop();
        }
        popped++;
    }
}

