private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> upperBounds = new ArrayList<>();
    if (keys.size() == 0) {
        return upperBounds;
    }
    upperBounds.add(0);
    for (int i = 1; i < keys.size(); i++) {
        int lowerBound = upperBounds.get(i - 1);
        int index = i;
        while (index < keys.size() && lowerBound >= keys.get(index)) {
            index++;
        }
        upperBounds.add(index);
    }
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys) {
    // sort the keys in descending order
    Collections.reverse(keys);

    // find the minimum lower bound for every key
    Map<Integer, Integer> lowerBounds = new HashMap<>();
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        Integer lowerBound = Integer.MAX_VALUE;
        for (int j = i + 1; j < keys.size(); j++) {
            if (keys.get(j) > key) {
                lowerBound = Math.min(lowerBound, keys.get(j));
            }
        }
        lowerBounds.put(key, lowerBound);
    }

    // construct the upper bound list
    List<Integer> upperBounds = new ArrayList<>();
    for (Map.Entry<Integer, Integer> entry : lowerBounds.entrySet()) {
        upperBounds.add(entry.getValue());
    }

    return upperBounds;
}

public List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<K>(keys.size());
    int lo = 0;
    int hi = keys.size() - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        int bound = keys.get(mid);
        if (bound <= mid) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
        upperBounds.add(bound);
    }
    return upperBounds;
}

