}

private void checkIfPackedField() throws IOException {
    if (isEOF()) {
        return;
    }

    long startPosition = @this.getFilePointer();
    int controlByte = readByte();
    if (controlByte == 0) {
        @this.setIsPacked(true);
        @this.setPackedSize(readVInt());
        @this.setPackedValues(readBytes(readVInt()));
    } else if (controlByte == 1) {
        @this.setIsPacked(false);
        @this.setPackedSize(0);
        @this.setPackedValues(null);
    }
}

